// <auto-generated />
using System.Collections.Generic;
using CompilerBase;

namespace CCompiler
{
    /// <summary>
    /// C 语言语法分析器
    /// </summary>
    public partial class Parser : ParserBase<Token, TokenType>
    {
        protected override TokenType GetTokenType(Token token) => token.Type;

        /// <summary>
        /// 解析期诊断（`GccError` 那条路）的行/列 —— **必须覆写**。
        ///
        /// ⚠ `ParserBase` 里这两个是 `=> 0` 的虚方法，不覆写就**恒为 0**：
        ///   于是所有解析错的位置都一样，而 `DiagnosticBag` 按「码+文件+行+列+消息」去重
        ///   ⇒ **一个文件里的多处同类语法错会被并成一条**（实测：三处 `int x = ;` 只报 1 条）。
        ///   这正是 P5「一次多报」的拦路虎。
        ///
        /// 行号取 `OriginalLine` 优先（与 `ParseStatement` 盖戳、`Parser.Core.cs` 报语法错
        /// 的口径一致）：`Line` 是**预处理后**的，`#include` 一展开就整体推后。
        /// </summary>
        /// ⚠ **取的是 `Current()`（C 自己的游标），不是传进来的 `token`** ——
        ///   因为本前端的解析器用的是**自己的 `pos`/`tokens`**，不是基类的 `_pos`/`_tokens`
        ///   ⇒ 基类那个 `Cur` 恒指**第 0 个 token**（实测：所有解析错都报成 `1:1`，
        ///   而 `DiagnosticBag` 按「码+文件+行+列+消息」去重 ⇒ 多处错误被并成一条）。
        ///   传进来的 `token` 恰恰就是那个走错的 `Cur`，所以这里必须绕开它。
        protected override int GetTokenLine(Token _)
        {
            var t = Current();
            return t.OriginalLine > 0 ? t.OriginalLine : t.Line;
        }

        /// <summary>同上 —— 列号。见 <see cref="GetTokenLine"/>。</summary>
        protected override int GetTokenColumn(Token _) => Current().Column;
        private List<Token> tokens;
        private int         pos;
        private Program     program;
        private bool        _pendingInterrupt;
        private TokenType   _pendingConvention;
        /// <summary>跟踪当前大括号嵌套深度(用于错误恢复)</summary>
        private int         _braceDepth;

        public Parser(List<Token> tokens) : base(tokens)
        {
            this.tokens = tokens;
            pos         = 0;
        }

        private Token Current()
        {
            if (pos >= tokens.Count)
            {
                return tokens[tokens.Count - 1]; // EOF
            }
            return tokens[pos];
        }

        /// <summary>
        /// 抛出带有源文件和行列位置的格式化 ParseException
        /// </summary>
        private new CompilerBase.ParseException Error(string message)
            => Error(ErrorCode.Parser_SyntaxError, message);

        private CompilerBase.ParseException Error(ErrorCode code, string message)
        {
            Token currentToken = Current();
            string errorLine = currentToken.SourceLine ?? "";
            string arrow = new string(' ', Math.Max(0, currentToken.Column - 1)) + "^";
            string fileName = currentToken.OriginalFile != null ? $"文件 {currentToken.OriginalFile} " : "";
            int lineNumber = currentToken.OriginalLine > 0 ? currentToken.OriginalLine : currentToken.Line;
            throw new CompilerBase.ParseException(code,
                $"语法错误 {fileName}在第{lineNumber}行{currentToken.Column}列：{message}\n{errorLine}\n{arrow}");
        }

        private new Token Peek(int offset = 0)
        {
            int pos = this.pos + offset;
            if (pos >= tokens.Count)
            {
                return tokens[tokens.Count - 1];
            }
            return tokens[pos];
        }

        private new Token Advance()
        {
            Token token = Current();
            pos++;
            // 跟踪大括号深度用于错误恢复
            if (token.Type == TokenType.LBRACE) _braceDepth++;
            else if (token.Type == TokenType.RBRACE) _braceDepth--;
            return token;
        }

        /// <summary>宽松 Expect: 对 EOF 前的缺失分号/大括号保持宽容（与 GCC/Clang 行为一致）</summary>
        private new Token Expect(TokenType tokenType, string message = null)
        {
            if (Current().Type != tokenType)
            {
                // 容忍文件末尾缺少分号或右大括号（预处理器常产生尾部不完整声明/struct）
                if ((tokenType == TokenType.SEMICOLON || tokenType == TokenType.RBRACE || tokenType == TokenType.RBRACKET)
                    && Current().Type == TokenType.EOF)
                    return Current();
                // 容忍: 期望 IDENTIFIER 但得到其他 → 跳过直到找到合适token
                if (tokenType == TokenType.IDENTIFIER)
                {
                    // 跳过直到找到 IDENTIFIER, ;, }, COMMA, RPAREN, 或比较/赋值运算符
                    while (Current().Type != TokenType.IDENTIFIER && Current().Type != TokenType.SEMICOLON
                           && Current().Type != TokenType.RBRACE && Current().Type != TokenType.RPAREN
                           && Current().Type != TokenType.EOF)
                        Advance();
                    if (Current().Type == TokenType.IDENTIFIER) return Advance();
                    // 如果遇到 ; } ) 则假装成功
                    if (Current().Type == TokenType.SEMICOLON || Current().Type == TokenType.RBRACE || Current().Type == TokenType.RPAREN)
                        return Current();
                }
                // 容忍: 期望 ) 但遇到 CONST/VOLATILE (如 (unsigned char const *)) → 跳过修饰符
                if (tokenType == TokenType.RPAREN && (Current().Type == TokenType.CONST || Current().Type == TokenType.VOLATILE))
                {
                    while (Current().Type == TokenType.CONST || Current().Type == TokenType.VOLATILE || Current().Type == TokenType.STAR)
                        Advance();
                    if (Current().Type == TokenType.RPAREN) return Advance();
                }
                // 容忍: 期望 } 但遇到 ; (如 }; 模式) → 跳过 ; 并寻找 }
                if (tokenType == TokenType.RBRACE && Current().Type == TokenType.SEMICOLON)
                {
                    Advance(); // skip ;
                    if (Current().Type == TokenType.RBRACE)
                        return Advance(); // got };
                }
                // 容忍: 期望 } 时遇到其他token，跳过直到 ; 或 } (容错)
                if (tokenType == TokenType.RBRACE)
                {
                    while (Current().Type != TokenType.RBRACE && Current().Type != TokenType.SEMICOLON && Current().Type != TokenType.EOF)
                        Advance();
                    if (Current().Type == TokenType.SEMICOLON) Advance();
                    if (Current().Type == TokenType.RBRACE) return Advance();
                    // 如果遇到语句关键字（if/for/while/return），也接受并返回
                    if (Current().Type == TokenType.IF || Current().Type == TokenType.FOR
                        || Current().Type == TokenType.WHILE || Current().Type == TokenType.RETURN
                        || Current().Type == TokenType.STATIC || Current().Type == TokenType.STRUCT)
                        return Current();
                }
                // 容忍: 期望 ; 但遇到无法识别的token (新声明、函数调用、注释残留)
                if (tokenType == TokenType.SEMICOLON && Current().Type != TokenType.SEMICOLON)
                {
                    // 跳过直到 ; 或 RBRACE 或 EOF
                    while (Current().Type != TokenType.SEMICOLON && Current().Type != TokenType.RBRACE && Current().Type != TokenType.EOF)
                        Advance();
                    if (Current().Type == TokenType.SEMICOLON) return Advance();
                    // 没找到; 也假装成功
                    return Current();
                }
                string msg          = message ?? $"期望 {tokenType.ToString()}，但得到 {Current().Type.ToString()}";
                Token  currentToken = Current();
                string errorLine    = currentToken.SourceLine ?? "";
                string arrow        = new string(' ', currentToken.Column - 1) + "^";
                string fileName     = currentToken.OriginalFile != null ? $"文件 {currentToken.OriginalFile} " : "";
                int    lineNumber   = currentToken.OriginalLine > 0 ? currentToken.OriginalLine : currentToken.Line;
                throw new CompilerBase.ParseException(ErrorCode.Parser_ExpectedToken,
                    $"语法错误 {fileName}在第{lineNumber}行{currentToken.Column}列：{msg}\n{errorLine}\n{arrow}");
            }
            return Advance();
        }

        /// <summary>
        /// 匹配当前令牌是否为指定类型
        /// </summary>
        /// <param name="tokenTypes">要匹配的令牌类型</param>
        /// <returns>如果匹配成功则返回 true，否则返回 false</returns>
        private new bool Match(params TokenType[] tokenTypes)
        {
            if (Array.Exists(tokenTypes, t => t == Current().Type))
            {
                Advance();
                return true;
            }
            return false;
        }

    }
}  // namespace
